const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5
pres.author = 'WorkspaceX';
pres.title = '团队协作';

const FONT = '微软雅黑';
const COLOR_PRIMARY = '1F4E79';
const COLOR_ACCENT = '2E75B6';
const COLOR_LIGHT = 'D6E4F0';
const COLOR_WHITE = 'FFFFFF';
const COLOR_DARK = '333333';

// ===== Slide 1: 封面 =====
const s1 = pres.addSlide();
s1.background = { color: COLOR_PRIMARY };
s1.addText('团队协作', {
  x: 0.8, y: 1.8, w: 11.7, h: 1.5,
  fontSize: 48, fontFace: FONT, bold: true, color: COLOR_WHITE, align: 'center'
});
s1.addText('打造高效、信任、目标一致的团队', {
  x: 0.8, y: 3.5, w: 11.7, h: 0.8,
  fontSize: 24, fontFace: FONT, color: COLOR_LIGHT, align: 'center'
});
s1.addShape(pres.ShapeType.rect, {
  x: 4.5, y: 4.6, w: 4.3, h: 0.06, fill: { color: COLOR_LIGHT }
});
s1.addText('2024 · 内部培训', {
  x: 0.8, y: 5.0, w: 11.7, h: 0.6,
  fontSize: 16, fontFace: FONT, color: COLOR_LIGHT, align: 'center'
});

// ===== Slide 2: 为什么需要团队协作 =====
const s2 = pres.addSlide();
s2.background = { color: COLOR_WHITE };
s2.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: COLOR_PRIMARY }
});
s2.addText('为什么需要团队协作？', {
  x: 0.6, y: 0.15, w: 12, h: 0.8,
  fontSize: 30, fontFace: FONT, bold: true, color: COLOR_WHITE
});

const reasons = [
  ['🎯', '目标对齐', '把个人努力汇聚到共同方向，减少重复与内耗'],
  ['⚡', '效率提升', '分工互补、并行推进，缩短交付周期'],
  ['💡', '创新涌现', '多元视角碰撞，激发单人难以产生的创意'],
  ['🛡️', '风险共担', '信息透明、互相补位，降低单点故障风险']
];

reasons.forEach((r, i) => {
  const yPos = 1.5 + i * 1.4;
  s2.addShape(pres.ShapeType.roundRect, {
    x: 0.8, y: yPos, w: 11.7, h: 1.15,
    fill: { color: COLOR_LIGHT }, rectRadius: 0.15
  });
  s2.addText(r[0], {
    x: 1.0, y: yPos + 0.1, w: 0.9, h: 0.9,
    fontSize: 32, align: 'center', valign: 'middle'
  });
  s2.addText(r[1], {
    x: 2.0, y: yPos + 0.1, w: 3, h: 0.5,
    fontSize: 20, fontFace: FONT, bold: true, color: COLOR_PRIMARY
  });
  s2.addText(r[2], {
    x: 2.0, y: yPos + 0.55, w: 10, h: 0.5,
    fontSize: 16, fontFace: FONT, color: COLOR_DARK
  });
});

// ===== Slide 3: 高效协作的四大支柱 =====
const s3 = pres.addSlide();
s3.background = { color: COLOR_WHITE };
s3.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: COLOR_PRIMARY }
});
s3.addText('高效协作的四大支柱', {
  x: 0.6, y: 0.15, w: 12, h: 0.8,
  fontSize: 30, fontFace: FONT, bold: true, color: COLOR_WHITE
});

const pillars = [
  ['信任', '心理安全\n敢于表达与试错'],
  ['沟通', '及时透明\n主动同步上下文'],
  ['责任', '角色清晰\n承诺可追踪'],
  ['反馈', '定期复盘\n持续改进机制']
];

pillars.forEach((p, i) => {
  const xPos = 0.6 + i * 3.15;
  s3.addShape(pres.ShapeType.roundRect, {
    x: xPos, y: 1.5, w: 2.9, h: 5.2,
    fill: { color: COLOR_ACCENT }, rectRadius: 0.2
  });
  s3.addText(p[0], {
    x: xPos, y: 1.8, w: 2.9, h: 1.0,
    fontSize: 28, fontFace: FONT, bold: true, color: COLOR_WHITE, align: 'center'
  });
  s3.addShape(pres.ShapeType.rect, {
    x: xPos + 0.6, y: 2.9, w: 1.7, h: 0.04, fill: { color: COLOR_LIGHT }
  });
  s3.addText(p[1], {
    x: xPos + 0.2, y: 3.2, w: 2.5, h: 3.2,
    fontSize: 18, fontFace: FONT, color: COLOR_WHITE, align: 'center', lineSpacingMultiple: 1.5
  });
});

// ===== Slide 4: 常见障碍与应对 =====
const s4 = pres.addSlide();
s4.background = { color: COLOR_WHITE };
s4.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: COLOR_PRIMARY }
});
s4.addText('常见障碍与应对策略', {
  x: 0.6, y: 0.15, w: 12, h: 0.8,
  fontSize: 30, fontFace: FONT, bold: true, color: COLOR_WHITE
});

const tableRows = [
  [{ text: '障碍', options: { bold: true, color: COLOR_WHITE, fill: { color: COLOR_PRIMARY }, fontSize: 18, fontFace: FONT, align: 'center' } },
   { text: '表现', options: { bold: true, color: COLOR_WHITE, fill: { color: COLOR_PRIMARY }, fontSize: 18, fontFace: FONT, align: 'center' } },
   { text: '应对策略', options: { bold: true, color: COLOR_WHITE, fill: { color: COLOR_PRIMARY }, fontSize: 18, fontFace: FONT, align: 'center' } }],
  [{ text: '信息孤岛', options: { fontSize: 16, fontFace: FONT } },
